class Solution {
public:
    int subsetXORSum(vector<int>& nums) {
        int orAll = 0;
        for (int x : nums) {
            orAll |= x;
        }
        int n = nums.size();
        int power = 1 << (n - 1);          // 2^{n-1}
        return orAll * power;
    }
};

